/* 滚动容器的优化 */
.scroll-container {
  overflow-y: auto;
  will-change: scroll-position;  /* 预告即将滚动 */
}

/* ====== 定义容器查询上下文 ====== */
/* 使用container-type声明元素为查询容器 */
.card-wrapper {
  container-type: inline-size;  /* 基于内联尺寸（宽度）查询 */
  container-name: card;         /* 命名容器，方便引用 */
  /* 简写：container: card / inline-size; */
}

/* ====== 使用容器查询 ====== */
/* @container规则：当容器满足条件时应用样式 */
@container card (min-width: 400px) {
  /* 当card容器宽度>=400px时 */
  .card {
    display: grid;
    grid-template-columns: 200px 1fr;  /* 图文并排 */
    gap: 16px;
  }

  .card__image {
    width: 200px;
    height: 150px;
  }

  .card__title {
    font-size: 1.5em;
  }
}

@container card (max-width: 399px) {
  /* 当card容器宽度<400px时（窄容器） */
  .card {
    display: flex;
    flex-direction: column;  /* 上下堆叠 */
  }

  .card__image {
    width: 100%;
    height: auto;
  }

  .card__title {
    font-size: 1.1em;
  }
}

/* ====== 容器查询长度单位 ====== */
/* cqw = 容器宽度的1%，cqh = 容器高度的1% */
.card__title {
  font-size: clamp(1em, 5cqw, 2em);
  /* 字体大小基于容器宽度动态调整 */
}

/* 不指定容器名，匹配最近的容器 */
@container (min-width: 300px) {
  .timeline-item {
    padding: 16px;
  }
}

/* ====== grid-template-areas：命名区域布局 ====== */
.page-layout {
  display: grid;
  grid-template-columns: 250px 1fr 250px;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
  /* 用命名区域描述布局，像画ASCII图一样直观 */
  grid-template-areas:
    "header  header  header"
    "sidebar main    aside"
    "footer  footer  footer";
  gap: 16px;
}

/* 将元素放置到命名区域 */
.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main    { grid-area: main; }
.aside   { grid-area: aside; }
.footer  { grid-area: footer; }

/* ====== auto-fill vs auto-fit ====== */
/* auto-fill：尽可能多地创建轨道，即使有些是空的 */
.auto-fill-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  /* minmax(250px, 1fr)：每列最小250px，最大等分剩余空间 */
  /* auto-fill：有多少空位就创建多少轨道 */
  gap: 16px;
}

/* auto-fit：拉伸现有项目填满空间 */
.auto-fit-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  /* auto-fit：现有项目拉伸填满，多余空轨道折叠为0 */
  gap: 16px;
}

/* ====== 响应式无需媒体查询 ====== */
/* minmax() + auto-fill 实现自适应列数 */
.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  /* 容器宽度>=200*n时自动增加列数 */
  /* 缩小窗口时自动减少列数 */
  /* 完全不需要写@media查询！ */
  gap: 12px;
}

/* ====== 密集填充模式 ====== */
.masonry-like {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-flow: dense;  /* 密集填充：小元素填充空隙 */
  gap: 8px;
}

/* ====== CSS架构设计：分层结构 ====== */

/* 第一层：设计令牌（Design Tokens） */
/* 所有设计变量集中管理，是整个样式系统的基础 */
:root {
  /* 颜色系统 */
  --color-primary-100: #dbeafe;
  --color-primary-500: #3b82f6;
  --color-primary-900: #1e3a5f;

  /* 间距系统（基于4px的倍数） */
  --space-1: 4px;
  --space-2: 8px;
  --space-4: 16px;
  --space-6: 24px;
  --space-8: 32px;

  /* 字体系统 */
  --font-sans: 'Inter', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  /* 阴影层级 */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px rgba(0,0,0,0.1);
}

/* 第二层：全局重置与基础样式 */
/* 统一浏览器默认样式，建立全局基线 */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font-sans);
  line-height: 1.6;
  color: #1a1a2e;
}

/* 第三层：工具类（Utility Classes） */
/* 单一职责的原子化类，组合使用构建布局 */
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-4 { gap: var(--space-4); }
.p-4 { padding: var(--space-4); }
.text-center { text-align: center; }

